/** Generate the Chrome wire validator from the server's actual TypeScript source. */
import { join } from "node:path";
const result = await Bun.build({
  entrypoints: [join(import.meta.dir, "../lib/browser-validation.ts")],
  target: "browser",
  format: "esm",
  minify: false,
});
if (!result.success) throw new Error(result.logs.join("\n"));
const content =
  "// Generated by bun run scripts/build-browser-contract.ts. Do not edit.\n" +
  (await result.outputs[0]!.text());
const path = join(import.meta.dir, "browser-chrome-extension/protocol.js");
if (process.argv.includes("--check")) {
  if ((await Bun.file(path).text()) !== content)
    throw new Error("Chrome protocol is stale; regenerate it");
} else await Bun.write(path, content);
